    "topic_ai_prompt_template_builder_row_sketch_prompt_generator_job": "Prompt de composición line-art / sketch",
    "topic_ai_prompt_template_builder_row_sketch_prompt_generator_need": "Medio, estilo de línea y controles de composición.",
    "topic_ai_prompt_template_builder_row_sketch_prompt_generator_skip": "Necesitabas parámetros MJ fotorrealistas o un formulario de cliffhanger de short-drama.",
    "topic_ai_prompt_template_builder_card_sketch_prompt_generator": "Medio, estilo de línea y controles de composición.",
    "topic_ai_prompt_template_builder_row_film_prompt_builder_job": "Logline y beats de tres actos",
    "topic_ai_prompt_template_builder_row_film_prompt_builder_need": "Campos de estructura de cine de largo.",
    "topic_ai_prompt_template_builder_row_film_prompt_builder_skip": "Necesitabas ganchos de short-drama vertical (otro formulario) o un brief UX de producto.",
    "topic_ai_prompt_template_builder_card_film_prompt_builder": "Campos de estructura de cine de largo.",
    "topic_ai_prompt_template_builder_row_short_drama_prompt_generator_job": "Ganchos y cliffhangers de serial vertical",
    "topic_ai_prompt_template_builder_row_short_drama_prompt_generator_need": "Campos de episodio/gancho que lista esta página.",
    "topic_ai_prompt_template_builder_row_short_drama_prompt_generator_skip": "Necesitabas un constructor de tres actos de largo.",
    "topic_ai_prompt_template_builder_card_short_drama_prompt_generator": "Campos de episodio/gancho que lista esta página.",
    "topic_ai_prompt_template_builder_row_product_design_prompt_builder_job": "Brief UX: persona, wireframe, tokens",
    "topic_ai_prompt_template_builder_row_product_design_prompt_builder_need": "Campos de diseño de producto, no plantillas Kotlin de Android.",
    "topic_ai_prompt_template_builder_row_product_design_prompt_builder_skip": "Necesitabas prompts de agente Compose o SwiftUI: son páginas aparte.",
    "topic_ai_prompt_template_builder_card_product_design_prompt_builder": "Campos de diseño de producto, no plantillas Kotlin de Android.",
